ckground:#fff}.candidate-browser__status{padding:.7rem 0;color:#94a3b8;font-size:.75rem}.candidate-browser__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.55rem;max-height:360px;overflow:auto;padding-right:.2rem}.candidate-option{display:grid;grid-template-columns:58px minmax(0,1fr);align-items:center;gap:.65rem;padding:.5rem;border:1px solid #334155;border-radius:11px;background:#1e293b;color:#fff;text-align:left;cursor:pointer;transition:.18s}.candidate-option:hover{transform:translateY(-1px);border-color:#60a5fa;background:#243550}.candidate-option img{width:58px;height:72px;object-fit:cover;border-radius:8px}.candidate-option__body{min-width:0}.candidate-option strong,.candidate-option span{display:block}.candidate-option strong{font-size:.75rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.candidate-option span{margin-top:.2rem;font-size:.65rem;color:#94a3b8}.candidate-option-loading{grid-column:1/-1;padding:.75rem;text-align:center;color:#94a3b8;font-size:.74rem}
