@section('js')
<template id="packageMediaManagerTemplate"><section class="package-media-manager"><div class="package-media-manager__head"><div><span>MEDIA KAMPANYE</span><h6>Foto bersama &amp; galeri live</h6><p>Seret foto ke area unggah. Setiap foto akan dipotong agar proporsinya rapi di semua tampilan.</p></div><i class="fas fa-images"></i></div><div class="row"><div class="col-md-5 mb-3 mb-md-0"><button type="button" class="package-media-dropzone" data-input="campaignPhotoInput"><i class="fas fa-image"></i><strong>Foto bersama kandidat</strong><small>Seret atau pilih satu foto utama</small></button><div id="campaignMediaPreview" class="package-media-preview" hidden><img alt="Pratinjau foto bersama"><span id="campaignPhotoHint">Foto utama paket.</span></div></div><div class="col-md-7"><button type="button" class="package-media-dropzone package-media-dropzone--gallery" data-input="livePhotosInput"><i class="fas fa-cloud-upload-alt"></i><strong>Galeri live polling</strong><small>Seret beberapa foto · maksimal 6 foto</small></button><div id="livePhotosHint" class="package-media-hint">Belum ada galeri live.</div><div id="liveMediaPreview" class="package-media-grid"></div></div></div></section></template>
<div class="modal fade" id="packageCropModal" tabindex="-1" data-backdrop="static" data-keyboard="false"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><small>RAPIKAN FOTO</small><h5 class="modal-title">Atur area foto</h5></div><button type="button" class="close cancel-package-crop" aria-label="Tutup"><span>&times;</span></button></div><div class="modal-body package-crop-body"><img id="packageCropImage" alt="Crop foto kampanye"></div><div class="modal-footer"><small class="text-muted mr-auto">Rasio 16:7 untuk tampilan paket dan layar live.</small><button type="button" class="btn btn-light cancel-package-crop">Batal</button><button type="button" class="btn btn-primary" id="savePackageCrop"><i class="fas fa-check mr-1"></i>Pakai Foto</button></div></div></div></div>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/cropperjs@1.6.1/dist/cropper.min.css">
<script src="https://cdn.jsdelivr.net/npm/cropperjs@1.6.1/dist/cropper.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
const packageForm=document.getElementById('packageForm');if(packageForm){const photoControls=document.createElement('div');photoControls.className='row package-photo-controls';photoControls.innerHTML='<div class="col-md-6 form-group"><label><i class="fas fa-image text-primary mr-1"></i>Foto Bersama Kandidat</label><label class="btn btn-sm btn-outline-primary d-block text-left mb-1" for="campaignPhotoInput"><i class="fas fa-upload mr-1"></i>Unggah foto utama</label><small class="text-muted d-block" id="campaignPhotoHint">Foto utama paket dan fallback ketika foto profil kandidat tidak tersedia.</small></div><div class="col-md-6 form-group"><label><i class="fas fa-images text-primary mr-1"></i>Galeri Live Polling</label><label class="btn btn-sm btn-outline-primary d-block text-left mb-1" for="livePhotosInput"><i class="fas fa-images mr-1"></i>Unggah hingga 6 foto</label><small class="text-muted d-block" id="livePhotosHint">Foto akan bergantian otomatis di layar live. Upload baru menggantikan galeri sebelumnya.</small></div>';
document.querySelector('#packageForm .candidate-assignment').before(photoControls);
document.getElementById('campaignPhotoInput').addEventListener('change',function(){document.getElementById('campaignPhotoHint').textContent=this.files[0]?'Foto dipilih: '+this.files[0].name:'Foto utama paket dan fallback ketika foto profil kandidat tidak tersedia.'});
document.getElementById('livePhotosInput').addEventListener('change',function(){document.getElementById('livePhotosHint').textContent=this.files.length?this.files.length+' foto siap diunggah; galeri lama akan diganti.':'Foto akan bergantian otomatis di layar live. Upload baru menggantikan galeri sebelumnya.'});}
let galleryPhotos=[],galleryIndex=0;const showGallery=()=>{const photo=galleryPhotos[galleryIndex];if(!photo)return;document.getElementById('packageGalleryImage').src=photo;document.getElementById('packageGalleryCount').textContent=(galleryIndex+1)+' dari '+galleryPhotos.length+' foto'};$(document).on('click','.package-gallery-open',function(){galleryPhotos=JSON.parse(this.dataset.photos||'[]');galleryIndex=0;document.getElementById('packageGalleryTitle').textContent=this.dataset.title;showGallery();$('#packageGalleryModal').modal('show')});$('#packageGalleryPrev').on('click',()=>{if(!galleryPhotos.length)return;galleryIndex=(galleryIndex-1+galleryPhotos.length)%galleryPhotos.length;showGallery()});$('#packageGalleryNext').on('click',()=>{if(!galleryPhotos.length)return;galleryIndex=(galleryIndex+1)%galleryPhotos.length;showGallery()});
if(packageForm){document.getElementById('livePhotosHint').textContent='Maksimal 6 foto. Foto baru ditambahkan ke galeri yang ada.';document.getElementById('livePhotosInput').addEventListener('change',function(){document.getElementById('livePhotosHint').textContent=this.files.length?this.files.length+' foto siap ditambahkan ke galeri.':'Maksimal 6 foto. Foto baru ditambahkan ke galeri yang ada.'});}
const packages=@json($packageData);
const voterMonitor=document.getElementById('voterMonitor');
if(voterMonitor){let voterPage=1,voterLast=1,voterTimer;const csrf=document.querySelector('meta[name="csrf-token"]')?.content;const esc=value=>$('<div>').text(value??'').html();const loadVoters=async()=>{const p=new URLSearchParams({page:voterPage,type:$('#voterType').val(),tingkat:$('#voterLevel').val(),kelas_id:$('#voterClass').val(),search:$('#voterSearch').val().trim(),status:voterMonitor.dataset.status||''});const r=await fetch(voterMonitor.dataset.url+'?'+p,{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();voterLast=d.pagination.last;$('#voterTotal').text(Number(d.pagination.total).toLocaleString('id-ID')+' pemilih');$('#voterPage').text('Halaman '+d.pagination.page+' dari '+d.pagination.last);$('#voterPrev').prop('disabled',voterPage<=1);$('#voterNext').prop('disabled',voterPage>=voterLast);$('#voterRows').html(d.rows.length?d.rows.map(v=>`<tr><td><strong>${esc(v.name)}</strong><div class="small text-muted">${esc(v.identity||'-')} · ${v.type==='student'?'Siswa':'GTK'}</div></td><td>${esc(v.scope)}</td><td>${v.voted?'<span class="badge badge-success"><i class="fas fa-lock mr-1"></i>Sudah memilih</span>':'<span class="badge badge-warning">Belum memilih</span>'}</td><td>${esc(v.voted_at||'-')}</td><td class="text-right">${v.can_unlock?`<button class="btn btn-sm btn-outline-warning unlock-voter" data-id="${v.id}" data-name="${esc(v.name)}"><i class="fas fa-unlock-alt"></i> Unlock</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="text-center text-muted py-3">Tidak ada pemilih sesuai filter.</td></tr>')};$('#voterType,#voterLevel,#voterClass').on('change',function(){if(this.id==='voterLevel')$('#voterClass option').each(function(){$(this).toggle(!this.dataset.level||this.dataset.level===this.value)});voterPage=1;loadVoters()});$('#voterSearch').on('input',()=>{clearTimeout(voterTimer);voterTimer=setTimeout(()=>{voterPage=1;loadVoters()},300)});$('#voterPrev').on('click',()=>{if(voterPage>1){voterPage--;loadVoters()}});$('#voterNext').on('click',()=>{if(voterPage<voterLast){voterPage++;loadVoters()}});$(document).on('click','.detail-stat-link',function(){voterMonitor.dataset.status=this.dataset.voterStatus==='all'?'':this.dataset.voterStatus;voterPage=1;document.getElementById('voterMonitor').scrollIntoView({behavior:'smooth',block:'start'});loadVoters()});$(document).on('click','.unlock-voter',function(){const b=this;Swal.fire({icon:'warning',title:'Unlock hak pilih?',text:b.dataset.name+' harus memilih ulang. Suara sebelumnya akan dibatalkan.',showCancelButton:true,confirmButtonText:'Ya, unlock',cancelButtonText:'Batal'}).then(async x=>{if(!x.isConfirmed)return;const r=await fetch(voterMonitor.dataset.unlockTemplate.replace('__VOTER__',b.dataset.id),{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'}}),d=await r.json();if(!r.ok)return Swal.fire('Belum dapat diproses',d.message,'error');Swal.fire('Berhasil',d.message,'success');loadVoters()})});loadVoters()}
