const candidatesLocked=@json($election->status==='paused');
let activeCandidateField=null,candidateSearchTimer=null,candidateRequest=null,visibleCandidates={},candidatePage=1,candidateHasMore=false,candidateLoading=false,candidateSearchValue='';
function escapeHtml(value){return $('<div>').text(value??'').html()}
function selectedCandidateIds(exceptField=null){const f=document.getElementById('packageForm');return candidateFields.filter(k=>k!==exceptField&&f.elements[k].value).map(k=>f.elements[k].value)}
function renderCandidateRole(field,student=null){const card=document.querySelector(`.candidate-role[data-field="${field}"]`),input=document.getElementById('packageForm').elements[field],img=card.querySelector('img'),icon=card.querySelector('.candidate-role__photo i'),button=card.querySelector('button');input.value=student?.id||'';card.querySelector('strong').textContent=student?.name||'Belum dipilih';card.querySelector('small').textContent=student?`${student.class} · NISN ${student.nisn||'-'}`:'Klik untuk memilih siswa';if(student){img.src=student.photo;img.alt=student.name;img.hidden=false;icon.hidden=true}else{img.hidden=true;img.removeAttribute('src');icon.hidden=false}button.innerHTML=candidatesLocked?'<i class="fas fa-lock mr-1"></i>Terkunci':(student?'<i class="fas fa-exchange-alt mr-1"></i>Ganti ':'<i class="fas fa-search mr-1"></i>Pilih ')+card.querySelector('span').textContent}
function resetCandidateRoles(){candidateFields.forEach(field=>renderCandidateRole(field));document.getElementById('candidateBrowser').hidden=true;document.getElementById('candidateSearch').value='';visibleCandidates={};candidatePage=1;candidateHasMore=false;candidateLoading=false;candidateSearchValue=''}
function candidateOptionMarkup(student){return `<button type="button" class="candidate-option" data-student-id="${escapeHtml(student.id)}"><img src="${escapeHtml(student.photo)}" alt="${escapeHtml(student.name)}" loading="lazy"><div class="candidate-option__body"><strong>${escapeHtml(student.name)}</strong><span>${escapeHtml(student.class)} · NISN ${escapeHtml(student.nisn||'-')}</span></div></button>`}
async function loadCandidates(search='',append=false){if(!activeCandidateField||(append&&(candidateLoading||!candidateHasMore)))return;const status=document.getElementById('candidateBrowserStatus'),grid=document.getElementById('candidateBrowserGrid');if(!append){if(candidateRequest)candidateRequest.abort();candidatePage=1;candidateHasMore=false;candidateSearchValue=search;visibleCandidates={};grid.innerHTML='';status.textContent='Memuat siswa yang tersedia...'}candidateLoading=true;const request=new AbortController();candidateRequest=request;const requestedPage=append?candidatePage+1:1;const params=new URLSearchParams({search:candidateSearchValue,current_package_id:document.getElementById('currentPackageId').value,page:requestedPage});selectedCandidateIds(activeCandidateField).forEach(id=>params.append('exclude_ids[]',id));if(append)grid.insertAdjacentHTML('beforeend','<div class="candidate-option-loading"><i class="fas fa-circle-notch fa-spin mr-1"></i>Memuat siswa berikutnya...</div>');try{const response=await fetch(candidateUrl+'?'+params.toString(),{headers:{Accept:'application/json'},signal:request.signal});if(!response.ok)throw new Error('Gagal memuat kandidat');const data=await response.json();grid.querySelector('.candidate-option-loading')?.remove();data.students.forEach(student=>visibleCandidates[student.id]=student);grid.insertAdjacentHTML('beforeend',data.students.map(candidateOptionMarkup).join(''));candidatePage=data.pagination.page;candidateHasMore=data.pagination.has_more;status.textContent=data.pagination.total?`${Object.keys(visibleCandidates).length} dari ${data.pagination.total} siswa ditampilkan${candidateHasMore?' · gulir ke bawah untuk memuat lagi':''} · siswa yang sudah dipakai disembunyikan`:'Tidak ada siswa yang sesuai.'}catch(error){grid.querySelector('.candidate-option-loading')?.remove();if(error.name!=='AbortError')status.textContent='Data kandidat gagal dimuat. Silakan coba lagi.'}finally{if(candidateRequest===request)candidateLoading=false}}
$(document).on('click','.btn-open-candidate',function(){if(candidatesLocked)return;activeCandidateField=this.dataset.field;document.getElementById('candidateRoleLabel').textContent=this.dataset.label;document.getElementById('candidateBrowser').hidden=false;document.getElementById('candidateSearch').value='';loadCandidates();setTimeout(()=>document.getElementById('candidateSearch').focus(),100)});
$(document).on('click','.candidate-option',function(){renderCandidateRole(activeCandidateField,visibleCandidates[this.dataset.studentId]);document.getElementById('candidateBrowser').hidden=true;activeCandidateField=null});
