$('.confirm-form').on('submit',function(e){e.preventDefault();const f=this;Swal.fire({icon:'question',title:'Konfirmasi',text:f.dataset.confirm,showCancelButton:true,confirmButtonText:'Ya, lanjutkan',cancelButtonText:'Batal',confirmButtonColor:'#2563eb'}).then(r=>{if(r.isConfirmed)f.submit()})});
