const livePolling=document.getElementById('livePolling');if(livePolling){const refreshLivePolling=async()=>{const icon=document.getElementById('livePollingIcon');icon.classList.add('fa-spin');try{const response=await fetch(livePolling.dataset.url,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();document.getElementById('liveVoted').textContent=Number(data.voted).toLocaleString('id-ID');document.getElementById('liveRemaining').textContent=Number(data.remaining).toLocaleString('id-ID');document.getElementById('liveTurnout').textContent=data.turnout+'%';document.getElementById('livePollingTime').textContent=data.updated_at;data.packages.forEach(item=>{const row=document.querySelector(`[data-package-id="${item.id}"]`);if(!row)return;row.querySelector('.live-bar span').style.width=item.percentage+'%';row.querySelector('.live-package-value strong').textContent=Number(item.votes).toLocaleString('id-ID');row.querySelector('.live-package-value span').textContent=item.percentage+'%'})}finally{icon.classList.remove('fa-spin')}};setInterval(()=>{if(!document.hidden)refreshLivePolling()},3000)}
