<script>
(() => {
    const form = document.getElementById('packageForm');
    if (!form) return;

    const assignment = form.querySelector('.candidate-assignment');
    const template = document.getElementById('packageMediaManagerTemplate');
    form.querySelector('.package-photo-controls')?.remove();
    assignment.before(template.content.cloneNode(true));

    const campaignInput = document.getElementById('campaignPhotoInput');
    const galleryInput = document.getElementById('livePhotosInput');
    const campaignPreview = document.getElementById('campaignMediaPreview');
    const campaignPreviewImage = campaignPreview.querySelector('img');
    const campaignHint = document.getElementById('campaignPhotoHint');
    const galleryPreview = document.getElementById('liveMediaPreview');
    const galleryHint = document.getElementById('livePhotosHint');
    const cropModal = $('#packageCropModal');
    const cropImage = document.getElementById('packageCropImage');
    document.querySelector('#packageCropModal .modal-footer small').textContent = 'Rasio awal mengikuti foto unggahan. Tarik sisi atau sudut mana pun bila perlu.';
    let cropper = null;
    let cropQueue = [];
    let activeCrop = null;
    let existingGalleryCount = 0;
    let existingGallery = [];

    const toFile = (blob, source) => new File([blob], `${source.name.replace(/\.[^.]+$/, '') || 'foto-kampanye'}.jpg`, { type: 'image/jpeg' });
    const setFiles = (input, files) => {
        const transfer = new DataTransfer();
        files.forEach(file => transfer.items.add(file));
        input.files = transfer.files;
    };
    const thumbnail = (url, label) => `<figure><img src="${url}" alt="${label}"><figcaption>${label}</figcaption></figure>`;
    const renderGallery = (existing = [], pending = []) => {
        galleryPreview.innerHTML = [
            ...existing.map((url, index) => thumbnail(url, `Tersimpan ${index + 1}`)),
            ...pending.map((file, index) => thumbnail(URL.createObjectURL(file), `Baru ${index + 1}`)),
        ].join('');
        const total = existing.length + pending.length;
        galleryHint.textContent = total ? `${existing.length} tersimpan · ${pending.length} foto baru siap disimpan (maksimal 6).` : 'Belum ada galeri live. Seret foto untuk menambah galeri.';
    };
    const renderMedia = packageData => {
        const campaign = packageData?.campaignPhoto;
        existingGallery = packageData?.livePhotos || [];
        existingGalleryCount = existingGallery.length;
        if (campaign) {
            campaignPreview.hidden = false;
            campaignPreviewImage.src = campaign;
            campaignHint.textContent = 'Foto utama yang tersimpan. Unggah foto baru untuk mengganti.';
        } else {
            campaignPreview.hidden = true;
            campaignPreviewImage.removeAttribute('src');
            campaignHint.textContent = 'Belum ada foto utama.';
        }
        renderGallery(existingGallery, []);
    };
    const resetMedia = () => {
        existingGalleryCount = 0;
        existingGallery = [];
        campaignPreview.hidden = true;
        campaignPreviewImage.removeAttribute('src');
        campaignHint.textContent = 'Belum ada foto utama.';
        renderGallery([], []);
    };

    const closeCrop = () => {
        cropModal.modal('hide');
        if (cropper) { cropper.destroy(); cropper = null; }
        if (cropImage.src.startsWith('blob:')) URL.revokeObjectURL(cropImage.src);
        cropImage.removeAttribute('src');
        activeCrop = null;
    };
    const openNextCrop = () => {
        activeCrop = cropQueue.shift();
        if (!activeCrop) return;
        cropImage.src = URL.createObjectURL(activeCrop.file);
        cropModal.one('shown.bs.modal', () => {
            if (typeof window.Cropper !== 'function') {
                Swal.fire('Editor foto belum siap', 'Muat ulang halaman lalu coba kembali.', 'error');
                closeCrop();
                return;
            }
            const originalRatio = cropImage.naturalWidth && cropImage.naturalHeight ? cropImage.naturalWidth / cropImage.naturalHeight : NaN;
            cropper = new window.Cropper(cropImage, { aspectRatio: NaN, initialAspectRatio: originalRatio, viewMode: 1, dragMode: 'move', autoCropArea: .9, cropBoxResizable: true, cropBoxMovable: true, responsive: true, background: false });
        }).modal('show');
    };
    const cropFiles = (input, files) => {
        const imageFiles = Array.from(files).filter(file => /^image\/(jpeg|png|webp)$/.test(file.type));
        if (!imageFiles.length) return;
        if (input === galleryInput && existingGalleryCount + imageFiles.length > 6) {
            Swal.fire('Galeri penuh', `Maksimal 6 foto. Saat ini sudah ada ${existingGalleryCount} foto tersimpan.`, 'warning');
            input.value = '';
            return;
        }
        input.value = '';
        cropQueue = imageFiles.map(file => ({ file, input, output: [] }));
        openNextCrop();
    };

    document.querySelectorAll('.package-media-dropzone').forEach(zone => {
        const input = document.getElementById(zone.dataset.input);
        zone.addEventListener('click', () => input.click());
        ['dragenter', 'dragover'].forEach(eventName => zone.addEventListener(eventName, event => { event.preventDefault(); zone.classList.add('is-dragover'); }));
        ['dragleave', 'drop'].forEach(eventName => zone.addEventListener(eventName, event => { event.preventDefault(); zone.classList.remove('is-dragover'); }));
        zone.addEventListener('drop', event => cropFiles(input, event.dataTransfer.files));
    });
    campaignInput.addEventListener('change', event => cropFiles(campaignInput, event.target.files));
    galleryInput.addEventListener('change', event => cropFiles(galleryInput, event.target.files));
    document.querySelectorAll('.cancel-package-crop').forEach(button => button.addEventListener('click', () => { cropQueue = []; closeCrop(); }));
    document.getElementById('savePackageCrop').addEventListener('click', () => {
        if (!cropper || !activeCrop) return;
        const button = document.getElementById('savePackageCrop');
        button.disabled = true;
        cropper.getCroppedCanvas({ imageSmoothingQuality: 'high' }).toBlob(blob => {
            button.disabled = false;
            if (!blob) return;
            activeCrop.output.push(toFile(blob, activeCrop.file));
            const target = activeCrop.input;
            const output = activeCrop.output;
            closeCrop();
            if (cropQueue.length) {
                cropQueue[0].output = target === galleryInput ? [...Array.from(galleryInput.files), ...output] : output;
                openNextCrop();
                return;
            }
            const files = target === galleryInput ? [...Array.from(galleryInput.files), ...output] : output;
            setFiles(target, files);
            if (target === campaignInput) {
                campaignPreview.hidden = false;
                campaignPreviewImage.src = URL.createObjectURL(files[0]);
                campaignHint.textContent = 'Foto baru siap disimpan.';
            } else {
                renderGallery(existingGallery, files);
            }
        }, 'image/jpeg', .9);
    });

    $('[data-target="#packageModal"]').on('click', resetMedia);
    $('.btn-edit-package').on('click', function () { renderMedia(packages[$(this).data('id')]); });
    form.addEventListener('submit', event => {
        if (cropper || activeCrop) {
            event.preventDefault();
            Swal.fire('Selesaikan crop dahulu', 'Terapkan atau batalkan crop foto sebelum menyimpan Paket.', 'info');
        }
    });
})();
</script>
<script>
(() => {
    const monitor = document.getElementById('voterMonitor');
    if (!monitor) return;
    let page = 1, last = 1, timer, controller, sequence = 0;
    const esc = value => $('<div>').text(value ?? '').html();
    const replaceControl = id => { const old = document.getElementById(id), fresh = old.cloneNode(true); old.replaceWith(fresh); return fresh; };
    const type = replaceControl('voterType'), level = replaceControl('voterLevel'), kelas = replaceControl('voterClass'), search = replaceControl('voterSearch'), prev = replaceControl('voterPrev'), next = replaceControl('voterNext');
    const rows = document.getElementById('voterRows'), total = document.getElementById('voterTotal'), pageLabel = document.getElementById('voterPage');
    const renderMessage = (message, retry = false) => rows.innerHTML = `<tr><td colspan="5" class="text-center text-muted py-3">${message}${retry ? ' <button type="button" class="btn btn-sm btn-outline-primary ml-2" id="retryVoters"><i class="fas fa-redo mr-1"></i>Coba lagi</button>' : ''}</td></tr>`;
    const load = async () => {
        controller?.abort(); const request = controller = new AbortController(), current = ++sequence;
        monitor.setAttribute('aria-busy', 'true'); renderMessage('<i class="fas fa-circle-notch fa-spin mr-1"></i>Memuat data pemilih…');
        const params = new URLSearchParams({page, type:type.value, tingkat:level.value, kelas_id:kelas.value, search:search.value.trim(), status:monitor.dataset.status || ''});
        try {
            const response = await fetch(monitor.dataset.url + '?' + params, {headers:{Accept:'application/json'}, cache:'no-store', signal:request.signal});
            if (!response.ok) throw new Error('Permintaan tidak berhasil');
            const data = await response.json(); if (current !== sequence) return;
            last = data.pagination.last; total.textContent = Number(data.pagination.total).toLocaleString('id-ID') + ' pemilih'; pageLabel.textContent = 'Halaman ' + data.pagination.page + ' dari ' + last;
            prev.disabled = page <= 1; next.disabled = page >= last;
            rows.innerHTML = data.rows.length ? data.rows.map(v => `<tr><td><strong>${esc(v.name)}</strong><div class="small text-muted">${esc(v.identity || '-')} · ${v.type === 'student' ? 'Siswa' : 'GTK'}</div></td><td>${esc(v.scope)}</td><td>${v.voted ? '<span class="badge badge-success"><i class="fas fa-lock mr-1"></i>Sudah memilih</span>' : '<span class="badge badge-warning">Belum memilih</span>'}</td><td>${esc(v.voted_at || '-')}</td><td class="text-right">${v.can_unlock ? `<button class="btn btn-sm btn-outline-warning unlock-voter" data-id="${v.id}" data-name="${esc(v.name)}"><i class="fas fa-unlock-alt"></i> Unlock</button>` : '—'}</td></tr>`).join('') : '<tr><td colspan="5" class="text-center text-muted py-3">Tidak ada pemilih sesuai filter.</td></tr>';
        } catch (error) { if (error.name !== 'AbortError' && current === sequence) renderMessage('Data pemilih belum dapat dimuat.', true); }
        finally { if (current === sequence) monitor.removeAttribute('aria-busy'); }
    };
    [type, level, kelas].forEach(control => control.addEventListener('change', () => { if (control === level) [...kelas.options].forEach(option => option.hidden = !!option.dataset.level && option.dataset.level !== level.value); page = 1; load(); }));
    search.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(() => { page = 1; load(); }, 300); });
    prev.addEventListener('click', () => { if (page > 1) { page--; load(); } }); next.addEventListener('click', () => { if (page < last) { page++; load(); } });
    rows.addEventListener('click', event => { if (event.target.closest('#retryVoters')) load(); });
    document.addEventListener('click', event => { const card = event.target.closest('.detail-stat-link'); if (!card) return; event.stopImmediatePropagation(); monitor.dataset.status = card.dataset.voterStatus === 'all' ? '' : card.dataset.voterStatus; page = 1; monitor.scrollIntoView({behavior:'smooth', block:'start'}); load(); }, true);
    document.addEventListener('keydown', event => { const card = event.target.closest('.detail-stat-link'); if (!card || !['Enter', ' '].includes(event.key)) return; event.preventDefault(); card.click(); }, true);
    load();
})();
</script>
@stop
